  "kpis": [
    {
      "name": "Average User Rating",
      "description": "Mean customer rating (0–5 scale) across all bestselling books, segmented by genre and year."
    },
    {
      "name": "Average Book Price",
      "description": "Mean retail price of bestselling books, segmented by genre and year."
    },
    {
      "name": "Price-Rating Correlation Coefficient",
      "description": "Pearson correlation coefficient between book price and user rating across the full dataset."
    },
    {
      "name": "Average Review Count",
      "description": "Mean number of customer reviews per book, indicating engagement level and popularity."
    },
    {
      "name": "Author Bestseller Frequency",
      "description": "Number of times an author's book(s) appeared on the annual top-50 bestseller list over the decade."
    }
  ],
  "analysis_dimensions": [
    "Genre",
    "Year",
    "Price",
    "User Rating",
    "Author"
  ]
}

