cat << 'PYEOF' > /app/gen_report.py
import json
import pandas as pd
import numpy as np

with open('/app/analysis_results.json', 'r') as f:
    s = json.load(f)

df = pd.read_csv('/app/benchmark/data.csv')

# Prepare chart data
yearly = s['yearly_trends']
years = [r['Year'] for r in yearly]
avg_prices = [r['avg_price'] for r in yearly]
avg_ratings = [r['avg_rating'] for r in yearly]
avg_reviews = [r['avg_reviews'] for r in yearly]

# Yearly genre data
yg = s['yearly_genre_trends']
fiction_yearly = [r for r in yg if r['Genre'] == 'Fiction']
nonfiction_yearly = [r for r in yg if r['Genre'] == 'Non Fiction']

f_years = [r['Year'] for r in fiction_yearly]
f_prices = [r['avg_price'] for r in fiction_yearly]
f_ratings = [r['avg_rating'] for r in fiction_yearly]

nf_years = [r['Year'] for r in nonfiction_yearly]
nf_prices = [r['avg_price'] for r in nonfiction_yearly]
nf_ratings = [r['avg_rating'] for r in nonfiction_yearly]

# Scatter data
scatter = s['scatter_data']
fic_scatter = [{'x': r['Price'], 'y': r['User Rating']} for r in scatter if r['Genre'] == 'Fiction']
nfic_scatter = [{'x': r['Price'], 'y': r['User Rating']} for r in scatter if r['Genre'] == 'Non Fiction']

# Price segments
pseg = s['price_segments']
seg_labels = [r['Price_Segment'] for r in pseg]
seg_counts = [r['count'] for r in pseg]
seg_ratings = [r['avg_rating'] for r in pseg]

# Genre year distribution
gyd = s['genre_year_distribution']
gyd_years = [r['Year'] for r in gyd]
gyd_fiction = [r.get('Fiction', 0) for r in gyd]
gyd_nonfiction = [r.get('Non Fiction', 0) for r in gyd]

# Top authors
ta = s['top_authors']

# Genre comparison
gc = s['genre_comparison']
fic_gc = [r for r in gc if r['Genre'] == 'Fiction'][0]
nfic_gc = [r for r in gc if r['Genre'] == 'Non Fiction'][0]

# Reviews yearly
f_reviews_yearly = [r['avg_reviews'] for r in fiction_yearly]
nf_reviews_yearly = [r['avg_reviews'] for r in nonfiction_yearly]

html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Amazon Bestselling Books: Price vs. User Rating Trend Analysis (2009–2019)</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.1/dist/chart.umd.min.js"></script>
<style>
  :root {{
    --primary: #1e3a5f;
    --primary-light: #2c5282;
    --accent: #e07c24;
    --accent-light: #f0a050;
    --text: #2d3748;
    --text-light: #4a5568;
    --bg: #f7fafc;
    --card-bg: #ffffff;
    --border: #e2e8f0;
    --fiction: #3182ce;
    --nonfiction: #e07c24;
    --success: #38a169;
    --warning: #d69e2e;
  }}
  * {{ margin: 0; padding: 0; box-sizing: border-box; }}
  body {{
    font-family: 'Segoe UI', -apple-system, BlinkMacSystemFont, sans-serif;
    background: var(--bg);
    color: var(--text);
    line-height: 1.6;
  }}
  .container {{ max-width: 1100px; margin: 0 auto; padding: 0 24px; }}

  /* Cover */
  .cover {{
    background: linear-gradient(135deg, var(--primary) 0%, var(--primary-light) 100%);
    color: white;
    padding: 80px 0 60px;
    margin-bottom: 40px;
  }}
  .cover h1 {{ font-size: 2.4rem; font-weight: 700; margin-bottom: 12px; line-height: 1.2; }}
  .cover .subtitle {{ font-size: 1.15rem; opacity: 0.9; margin-bottom: 28px; max-width: 700px; }}
  .cover .meta {{ display: flex; gap: 32px; font-size: 0.9rem; opacity: 0.8; flex-wrap: wrap; }}
  .cover .meta span {{ display: flex; align-items: center; gap: 6px; }}

  /* KPI strip */
  .kpi-strip {{
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 16px;
    margin: -30px 0 40px;
    position: relative;
    z-index: 1;
  }}
  .kpi-card {{
    background: var(--card-bg);
    border-radius: 10px;
    padding: 20px 22px;
    box-shadow: 0 2px 12px rgba(0,0,0,0.08);
    text-align: center;
  }}
  .kpi-card .kpi-value {{ font-size: 1.9rem; font-weight: 700; color: var(--primary); }}
  .kpi-card .kpi-label {{ font-size: 0.82rem; color: var(--text-light); text-transform: uppercase; letter-spacing: 0.5px; margin-top: 4px; }}

  /* Sections */
  .section {{
    background: var(--card-bg);
    border-radius: 12px;
    padding: 36px 40px;
    margin-bottom: 32px;
    box-shadow: 0 1px 8px rgba(0,0,0,0.05);
  }}
  .section h2 {{
    font-size: 1.5rem;
    color: var(--primary);
    margin-bottom: 8px;
    padding-bottom: 12px;
    border-bottom: 2px solid var(--accent);
    display: inline-block;
  }}
  .section h3 {{
    font-size: 1.15rem;
    color: var(--primary-light);
    margin: 24px 0 10px;
  }}
  .section p {{ margin: 12px 0; color: var(--text-light); font-size: 0.95rem; }}

  /* Charts */
  .chart-container {{
    position: relative;
    margin: 20px 0;
    padding: 10px;
    background: #fafbfc;
    border-radius: 8px;
    border: 1px solid var(--border);
  }}
  .chart-row {{
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    margin: 20px 0;
  }}
  @media (max-width: 768px) {{
    .chart-row {{ grid-template-columns: 1fr; }}
  }}

  /* Tables */
  table {{
    width: 100%;
    border-collapse: collapse;
    margin: 16px 0;
    font-size: 0.9rem;
  }}
  thead {{ background: var(--primary); color: white; }}
  th {{ padding: 10px 14px; text-align: left; font-weight: 600; font-size: 0.82rem; text-transform: uppercase; letter-spacing: 0.5px; }}
  td {{ padding: 10px 14px; border-bottom: 1px solid var(--border); }}
  tbody tr:hover {{ background: #f0f4f8; }}
  .num {{ text-align: right; font-variant-numeric: tabular-nums; }}

  /* Callout */
  .callout {{
    background: linear-gradient(135deg, #ebf8ff 0%, #e6fffa 100%);
    border-left: 4px solid var(--primary-light);
    padding: 16px 20px;
    border-radius: 0 8px 8px 0;
    margin: 16px 0;
    font-size: 0.93rem;
  }}
  .callout.warning {{
    background: linear-gradient(135deg, #fffbeb 0%, #fef3c7 100%);
    border-left-color: var(--warning);
  }}
  .callout.insight {{
    background: linear-gradient(135deg, #f0fff4 0%, #c6f6d5 100%);
    border-left-color: var(--success);
  }}
  .callout strong {{ color: var(--primary); }}

  /* Comparison grid */
  .compare-grid {{
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    margin: 20px 0;
  }}
  .compare-card {{
    border-radius: 10px;
    padding: 24px;
    text-align: center;
  }}
  .compare-card.fiction {{
    background: linear-gradient(135deg, #ebf4ff 0%, #dbeafe 100%);
    border: 2px solid var(--fiction);
  }}
  .compare-card.nonfiction {{
    background: linear-gradient(135deg, #fff7ed 0%, #ffedd5 100%);
    border: 2px solid var(--nonfiction);
  }}
  .compare-card h4 {{ font-size: 1.1rem; margin-bottom: 14px; }}
  .compare-card .stat {{ font-size: 0.88rem; margin: 6px 0; color: var(--text-light); }}
  .compare-card .stat strong {{ font-size: 1.05rem; color: var(--text); }}

  /* Recommendations */
  .rec-list {{ list-style: none; padding: 0; }}
  .rec-list li {{
    padding: 14px 18px 14px 48px;
    margin: 10px 0;
    background: #f8fafc;
    border-radius: 8px;
    border-left: 4px solid var(--accent);
    position: relative;
    font-size: 0.93rem;
    color: var(--text-light);
  }}
  .rec-list li::before {{
    content: attr(data-num);
    position: absolute;
    left: 14px;
    top: 14px;
    width: 22px;
    height: 22px;
    background: var(--accent);
    color: white;
    border-radius: 50%;
    font-size: 0.75rem;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 700;
  }}
  .rec-list li strong {{ color: var(--text); }}

  /* Footer */
  .footer {{
    text-align: center;
    padding: 30px 0;
    color: var(--text-light);
    font-size: 0.82rem;
    border-top: 1px solid var(--border);
    margin-top: 20px;
  }}

  /* TOC */
  .toc {{
    background: var(--card-bg);
    border-radius: 12px;
    padding: 28px 36px;
    margin-bottom: 32px;
    box-shadow: 0 1px 8px rgba(0,0,0,0.05);
  }}
  .toc h3 {{ color: var(--primary); margin-bottom: 14px; font-size: 1.1rem; }}
  .toc ol {{ padding-left: 20px; }}
  .toc li {{ padding: 4px 0; font-size: 0.92rem; }}
  .toc a {{ color: var(--primary-light); text-decoration: none; }}
  .toc a:hover {{ text-decoration: underline; }}

  .badge {{
    display: inline-block;
    padding: 2px 10px;
    border-radius: 12px;
    font-size: 0.75rem;
    font-weight: 600;
    text-transform: uppercase;
  }}
  .badge-fiction {{ background: #dbeafe; color: var(--fiction); }}
  .badge-nonfiction {{ background: #ffedd5; color: #c2410c; }}
</style>
</head>
<body>

<!-- COVER -->
<div class="cover">
  <div class="container">
    <h1>Amazon Bestselling Books:<br>Price vs. User Rating Trend Analysis</h1>
    <p class="subtitle">A comprehensive analysis of how book pricing strategies relate to customer satisfaction across Fiction and Non-Fiction genres over a decade of Amazon bestseller data.</p>
    <div class="meta">
      <span>Period: 2009 – 2019</span>
      <span>Records: {s['total_records']} entries</span>
      <span>Unique Titles: {s['unique_books']}</span>
      <span>Report Date: April 2026</span>
    </div>
  </div>
</div>

<!-- KPI STRIP -->
<div class="container">
  <div class="kpi-strip">
    <div class="kpi-card">
      <div class="kpi-value">{s['avg_rating']}</div>
      <div class="kpi-label">Avg. User Rating</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-value">${s['avg_price']}</div>
      <div class="kpi-label">Avg. Book Price</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-value">{s['pearson_r']}</div>
      <div class="kpi-label">Price-Rating Correlation (r)</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-value">{int(s['avg_reviews']):,}</div>
      <div class="kpi-label">Avg. Reviews per Book</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-value">{s['top_authors'][0]['appearances']}</div>
      <div class="kpi-label">Max Author Appearances</div>
    </div>
  </div>

  <!-- TOC -->
  <div class="toc">
    <h3>Table of Contents</h3>
    <ol>
      <li><a href="#market-overview">Bestseller Market Overview (2009–2019)</a></li>
      <li><a href="#price-rating-correlation">Price vs. User Rating: Correlation Analysis</a></li>
      <li><a href="#genre-comparison">Fiction vs. Non-Fiction: Pricing and Rating Strategies</a></li>
      <li><a href="#temporal-trends">Year-over-Year Trends in Pricing and Ratings</a></li>
      <li><a href="#top-authors">Dominant Authors on the Bestseller List</a></li>
      <li><a href="#recommendations">Strategic Recommendations</a></li>
    </ol>
  </div>

  <!-- SECTION 1: MARKET OVERVIEW -->
  <div class="section" id="market-overview">
    <h2>1. Bestseller Market Overview (2009–2019)</h2>
    <p>This analysis covers <strong>{s['total_records']} bestseller entries</strong> across 11 years of Amazon's annual top-50 lists, representing <strong>{s['unique_books']} unique titles</strong> by <strong>{s['unique_authors']} distinct authors</strong>. The gap between entries and unique titles reflects perennial bestsellers that achieved top-50 status in multiple years.</p>

    <div class="chart-row">
      <div class="chart-container">
        <canvas id="genrePieChart" height="260"></canvas>
      </div>
      <div class="chart-container">
        <canvas id="genreYearBar" height="260"></canvas>
      </div>
    </div>

    <h3>Dataset at a Glance</h3>
    <table>
      <thead>
        <tr><th>Metric</th><th class="num">Overall</th><th class="num">Fiction</th><th class="num">Non-Fiction</th></tr>
      </thead>
      <tbody>
        <tr><td>Number of Entries</td><td class="num">{s['total_records']}</td><td class="num">{fic_gc['count']}</td><td class="num">{nfic_gc['count']}</td></tr>
        <tr><td>Share of Entries</td><td class="num">100%</td><td class="num">{s['genre_pcts'].get('Fiction', 0)}%</td><td class="num">{s['genre_pcts'].get('Non Fiction', 0)}%</td></tr>
        <tr><td>Avg. Price</td><td class="num">${s['avg_price']}</td><td class="num">${fic_gc['avg_price']}</td><td class="num">${nfic_gc['avg_price']}</td></tr>
        <tr><td>Avg. Rating</td><td class="num">{s['avg_rating']}</td><td class="num">{fic_gc['avg_rating']}</td><td class="num">{nfic_gc['avg_rating']}</td></tr>
        <tr><td>Avg. Reviews</td><td class="num">{int(s['avg_reviews']):,}</td><td class="num">{int(fic_gc['avg_reviews']):,}</td><td class="num">{int(nfic_gc['avg_reviews']):,}</td></tr>
        <tr><td>Price Range</td><td class="num">${s['min_price']} – ${s['max_price']}</td><td class="num">${fic_gc['min_price']} – ${fic_gc['max_price']}</td><td class="num">${nfic_gc['min_price']} – ${nfic_gc['max_price']}</td></tr>
        <tr><td>Rating Range</td><td class="num">{s['min_rating']} – {s['max_rating']}</td><td class="num">{fic_gc['min_rating']} – {fic_gc['max_rating']}</td><td class="num">{nfic_gc['min_rating']} – {nfic_gc['max_rating']}</td></tr>
      </tbody>
    </table>

    <div class="callout">
      <strong>Key Takeaway:</strong> Non-Fiction dominates the bestseller list at {s['genre_pcts'].get('Non Fiction', 0)}% of entries, despite Fiction titles generating significantly higher review volumes ({int(fic_gc['avg_reviews']):,} vs. {int(nfic_gc['avg_reviews']):,} avg. reviews). The price range for Non-Fiction (${nfic_gc['min_price']}–${nfic_gc['max_price']}) is considerably wider than Fiction (${fic_gc['min_price']}–${fic_gc['max_price']}), largely due to academic reference titles.
    </div>
  </div>

  <!-- SECTION 2: PRICE-RATING CORRELATION -->
  <div class="section" id="price-rating-correlation">
    <h2>2. Price vs. User Rating: Correlation Analysis</h2>
    <p>The central question of this analysis — whether higher prices correlate with higher customer satisfaction — is answered with statistical precision below.</p>

    <div class="chart-container" style="max-width:700px; margin: 20px auto;">
      <canvas id="scatterChart" height="400"></canvas>
    </div>

    <h3>Correlation Coefficients</h3>
    <table>
      <thead>
        <tr><th>Segment</th><th class="num">Pearson r</th><th class="num">p-value</th><th>Interpretation</th></tr>
      </thead>
      <tbody>
        <tr><td><strong>All Books</strong></td><td class="num"><strong>{s['pearson_r']}</strong></td><td class="num">{s['pearson_p']}</td><td>Weak negative correlation, statistically significant</td></tr>
        <tr><td><span class="badge badge-fiction">Fiction</span></td><td class="num">{s['pearson_r_fiction']}</td><td class="num">{s['pearson_p_fiction']}</td><td>{"Weak negative, significant" if s['pearson_p_fiction'] < 0.05 else "Not statistically significant"}</td></tr>
        <tr><td><span class="badge badge-nonfiction">Non-Fiction</span></td><td class="num">{s['pearson_r_non_fiction']}</td><td class="num">{s['pearson_p_non_fiction']}</td><td>{"Weak negative, significant" if s['pearson_p_non_fiction'] < 0.05 else "Not statistically significant"}</td></tr>
      </tbody>
    </table>

    <h3>Average Rating by Price Segment</h3>
    <div class="chart-container" style="max-width:700px; margin: 20px auto;">
      <canvas id="priceSegChart" height="320"></canvas>
    </div>

    <table>
      <thead>
        <tr><th>Price Segment</th><th class="num">Count</th><th class="num">Avg. Rating</th><th class="num">Avg. Reviews</th></tr>
      </thead>
      <tbody>
        {"".join(f'<tr><td>{r["Price_Segment"]}</td><td class="num">{r["count"]}</td><td class="num">{r["avg_rating"]}</td><td class="num">{int(r["avg_reviews"]):,}</td></tr>' for r in pseg)}
      </tbody>
